    title: 'Guild',
    hero: 'leader',
    source: 'External JSON block in example HTML (lib/examples/guild.html)',
    fetchedAt: new Date().toISOString().slice(0, 10)
  },

  buildPack(defaults) {
    const data = defaults.data;

    // ① entities from members (keyed by id, with name + kind)
    const entities = {};
